(function () {
  var KEY = "km_mockup_v2_db_1";
  function clone(o) { return JSON.parse(JSON.stringify(o)); }
  function load() {
    try {
      var raw = localStorage.getItem(KEY);
      if (raw) {
        var parsed = JSON.parse(raw);
        return Object.assign(clone(window.KM_SEED), parsed);
      }
    } catch (e) {}
    return clone(window.KM_SEED);
  }
  function save(data) {
    try { localStorage.setItem(KEY, JSON.stringify(data)); } catch (e) {}
    window.KM = data;
    return data;
  }
  function reset() {
    try { localStorage.removeItem(KEY); } catch (e) {}
    window.KM = clone(window.KM_SEED);
    return window.KM;
  }
  function nextId(list) {
    return (list || []).reduce(function (m, x) { return Math.max(m, Number(x && x.id) || 0); }, 0) + 1;
  }
  window.KM = load();
  window.KMStore = {
    get: function () { return window.KM; },
    save: save,
    reset: reset,
    nextId: nextId,
    reload: function () { window.KM = load(); return window.KM; }
  };
})();
